mapper.select:
select id, field_code, field_value, word_color, background_color, tips, remark, del_flag, create_by, create_time, update_by, update_time from t_remind_setting where del_flag = '0' and field_code = #{fieldCode} and INSTR(field_value, #{fieldValue}) > 0
order by create_time desc
order by ${orderStr}

WITH temp_table AS (
SELECT #{rowNumber}+2 row_numbers, #{data.fieldCode,jdbcType=VARCHAR} FIELD_CODE, #{data.fieldValue,jdbcType=VARCHAR} FIELD_VALUE
) select #{importLogId} importLogId, t.row_numbers errorRow, #{errorDetail} errorDetail, #{createBy} createBy, now() createTime from t_remind_setting m inner join temp_table t on m.FIELD_CODE = t.FIELD_CODE and m.FIELD_VALUE = t.FIELD_VALUE and m.del_flag ='0'

mapper.insert:
insert into t_remind_setting
(id,field_code,field_value,word_color,background_color,tips,remark,del_flag,create_by,create_time,update_by,update_time
)
select NULL id, x.*
from (

    select
    #{remindSetting.fieldCode,jdbcType=VARCHAR} field_code, #{remindSetting.fieldValue,jdbcType=VARCHAR}
    field_value,
    #{remindSetting.wordColor,jdbcType=VARCHAR} word_color, #{remindSetting.backgroundColor,jdbcType=VARCHAR}
    background_color, #{remindSetting.tips,jdbcType=VARCHAR} tips, #{remindSetting.remark,jdbcType=VARCHAR}
    remark,
    #{remindSetting.delFlag,jdbcType=VARCHAR} del_flag, #{remindSetting.createBy,jdbcType=VARCHAR} create_by,
    #{remindSetting.createTime,jdbcType=TIMESTAMP} create_time, #{remindSetting.updateBy,jdbcType=VARCHAR}
    update_by, #{remindSetting.updateTime,jdbcType=TIMESTAMP} update_time 

) x
